function validate([s1, s2]) {
  if (typeof s1 !== 'string' || typeof s2 !== 'string') return 's1 and s2 must be strings.';
  if (s1.length < 1 || s1.length > 100) return 's1 needs 1 to 100 characters.';
  if (s2.length !== s1.length) return 's1 and s2 must have the same length.';
  if (!/^[a-z]+$/.test(s1) || !/^[a-z]+$/.test(s2)) return 'Only lowercase English letters are allowed.';
  return null;
}

