function areAlmostEqual(s1, s2) {
  const diff = [];
  for (let i = 0; i < s1.length; i++) {
    if (s1[i] !== s2[i]) {
      diff.push(i);
      if (diff.length > 2) {
        return false;
      }
    }
  }

  if (diff.length === 0) {
    return true;
  }
  if (diff.length !== 2) {
    return false;
  }
  const [first, second] = diff;
  return s1[first] === s2[second] && s1[second] === s2[first];
}

