function areAlmostEqual(s1, s2) {
  // Try every swap of s1 (swapping inside s2 is symmetric) and compare.
  const chars = s1.split('');
  for (let i = 0; i < chars.length; i++) {
    for (let j = i; j < chars.length; j++) {
      const copy = chars.slice();
      const temp = copy[i];
      copy[i] = copy[j];
      copy[j] = temp;
      if (copy.join('') === s2) return true;
    }
  }
  return false;
}

