function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? int(80, 100) : int(1, 6);
  const letters = size === 'large' ? int(2, 26) : int(1, 3);
  const letter = () => String.fromCharCode(97 + int(0, letters - 1));
  const s1 = Array.from({ length: n }, letter);
  const s2 = s1.slice();
  const mode = rand();
  if (mode < 0.15) {
    // identical strings
  } else if (mode < 0.5) {
    const i = int(0, n - 1);
    const j = int(0, n - 1);
    [s2[i], s2[j]] = [s2[j], s2[i]];
  } else if (mode < 0.8) {
    const changes = int(1, 3);
    for (let k = 0; k < changes; k++) s2[int(0, n - 1)] = letter();
  } else {
    for (let k = 0; k < n; k++) s2[k] = letter();
  }
  return [s1.join(''), s2.join('')];
}
